  const exp = new Date(new Date(agora).getTime() + VALIDADE_DIAS * 86400000).toISOString();
  return (auditorias || []).filter((a) => a && a.audit_id && a.qa_status === 'aprovado' && (!a.diag_token || String(a.diag_expira_em || '') < agora))
