return gerarTokens($('Ler auditorias aprovadas').all().map((i) => i.json)).map((j) => ({ json: j }));

// ATOM2_W09 · Página privada do diagnóstico (link [link] do script "Pode enviar" e da entrega do N1).
// Token aleatório por auditoria aprovada, expira em 60 dias, página noindex. Só achados VERIFICADOS no site público,
// com URL, data e método. Sem preço (regra absoluta), sem promessa de posição/citação em IA, sem dado de paciente.
const VALIDADE_DIAS = 60;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const dataBR = (iso) => { const d = String(iso || '').slice(0, 10).split('-'); return d.length === 3 ? d[2] + '/' + d[1] + '/' + d[0] : ''; };

// Token: 32 caracteres hex (crypto do Node quando existir; senão Math.random, ainda inadivinhável na prática para este uso).
function novoToken() {
  try { if (typeof crypto !== 'undefined' && crypto.getRandomValues) { const a = new Uint8Array(16); crypto.getRandomValues(a); return Array.from(a, (b) => b.toString(16).padStart(2, '0')).join(''); } } catch (e) { /* segue */ }
  let s = '';
  while (s.length < 32) s += Math.floor(Math.random() * 16).toString(16);
  return s;
}

// 1) Gera link para auditorias aprovadas sem token (ou com token vencido).
function gerarTokens(auditorias, agoraISO, gerador) {
  const agora = agoraISO || new Date().toISOString();
  const g = gerador || novoToken;
  const exp = new Date(new Date(agora).getTime() + VALIDADE_DIAS * 86400000).toISOString();
  return (auditorias || []).filter((a) => a && a.audit_id && a.qa_status === 'aprovado' && (!a.diag_token || String(a.diag_expira_em || '') < agora))
    .map((a) => ({ audit_id: a.audit_id, diag_token: g(), diag_expira_em: exp, diag_vistas: 0 }));
}

// 2) Página. Devolve { status, html, auditoria?, evento? }.
const ROTULO = { conversao: 'Conversão e contato', seo: 'SEO', geo: 'Preparo para buscas com IA (GEO)', conteudo: 'Conteúdo', dados_estruturados: 'Informações para o Google', local: 'Presença local', mobile: 'Celular', tecnico: 'Técnico' };
function pagina(titulo, corpo) {
  return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><meta name="referrer" content="no-referrer"><title>${esc(titulo)}</title>
<style>
:root{--bg:#f6f7f9;--card:#fff;--tx:#1d2330;--mut:#5d6677;--bd:#e3e6ec;--pri:#2f5bd3;--alta:#b42318;--media:#b25e09;--baixa:#53627a}
@media (prefers-color-scheme:dark){:root{--bg:#12151b;--card:#1b2029;--tx:#e8ebf1;--mut:#9aa3b2;--bd:#2c3340;--pri:#7c9cff}}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--tx);font:16px/1.6 system-ui,-apple-system,Segoe UI,Roboto,sans-serif}
main{max-width:760px;margin:0 auto;padding:32px 16px 64px}h1{font-size:26px;line-height:1.25;margin:0 0 8px}.sub{color:var(--mut);margin:0 0 24px}
.card{background:var(--card);border:1px solid var(--bd);border-radius:12px;padding:18px 20px;margin:0 0 14px}.card.principal{border-left:4px solid var(--pri)}
h2{font-size:18px;margin:0 0 6px}.tag{display:inline-block;font-size:12px;font-weight:600;text-transform:uppercase;letter-spacing:.03em;margin:0 8px 6px 0;color:var(--mut)}
.sev-alta{color:var(--alta)}.sev-media{color:var(--media)}.sev-baixa{color:var(--baixa)}
.ev{font-size:14px;color:var(--mut);word-break:break-word}.rec{margin:8px 0 0}a{color:var(--pri)}
footer{margin-top:28px;font-size:13px;color:var(--mut)}
details summary{cursor:pointer;color:var(--mut);font-size:14px}.botao{display:inline-block;background:#1f7a4d;color:#fff;border-radius:8px;padding:10px 18px;margin:6px 8px 0 0;text-decoration:none;font-weight:600}.botao.sec{background:var(--pri)}.cta{border-color:var(--pri)}
</style></head><body><main>${corpo}</main></body></html>`;
}
// Chamada para ação: WhatsApp da ATOM (ATOM_WHATSAPP_NUMERO) com texto pronto, que o W08 classifica como interesse; agenda opcional (AGENDA_URL).
function botoes(cfg, nome) {
  const n = String((cfg || {}).ATOM_WHATSAPP_NUMERO || '').replace(/\D/g, '');
  const agenda = String((cfg || {}).AGENDA_URL || '');
  const wa = n.length >= 12 ? `<a class="botao" href="https://wa.me/${n}?text=${encodeURIComponent('Tenho interesse em entender melhor o diagnóstico da ' + nome)}" target="_blank" rel="noopener">Conversar no WhatsApp</a>` : '';
  const ag = /^https:\/\//.test(agenda) ? `<a class="botao sec" href="${esc(agenda)}" target="_blank" rel="noopener">Agendar 15 minutos</a>` : '';
  return wa || ag ? `<section class="card cta"><h2>Quer ver como resolver estes pontos?</h2><p>Em 15 minutos mostramos as melhorias, sem compromisso.</p>${wa}${ag}</section>` : '';
}
function renderizar(token, auditorias, empresas, achados, agoraISO, cfg) {
  const agora = agoraISO || new Date().toISOString();
  const naoEncontrado = { status: 404, html: pagina('Link indisponível', '<h1>Link indisponível</h1><p class="sub">Este link expirou ou não existe. Se você recebeu o diagnóstico da ATOM Digital, responda a mensagem que enviamos um link novo.</p>') };
  const t = String(token || '').trim();
  if (!/^[a-f0-9]{24,64}$/.test(t)) return naoEncontrado;
  const a = (auditorias || []).find((x) => x && x.diag_token === t);
  if (!a || a.qa_status !== 'aprovado' || String(a.diag_expira_em || '') < agora) return naoEncontrado;
  const e = (empresas || []).find((x) => x && x.company_id === a.company_id) || {};
  const lista = (achados || []).filter((f) => f && f.audit_id === a.audit_id && (f.usado_em === 'principal' || f.usado_em === 'resumo') && f.reviewer_status !== 'reprovado')
    .sort((x, y) => (x.usado_em === 'principal' ? -1 : y.usado_em === 'principal' ? 1 : 0) || ['alta', 'media', 'baixa'].indexOf(x.severity) - ['alta', 'media', 'baixa'].indexOf(y.severity));
  const SEV = { alta: 'Prioridade alta', media: 'Prioridade média', baixa: 'Melhoria complementar' };
  const cartoes = lista.map((f) => `<section class="card${f.usado_em === 'principal' ? ' principal' : ''}">
<span class="tag sev-${esc(f.severity)}">${SEV[f.severity] || ''}</span><span class="tag">${esc(ROTULO[f.category] || f.category || '')}</span>
<h2>${esc(f.claim)}</h2>
${f.recommendation ? `<p class="rec"><b>Sugestão:</b> ${esc(f.recommendation)}</p>` : ''}
<details><summary>Ver a evidência</summary><p class="ev">${esc(f.evidence)}<br>Onde: <a href="${esc(f.source_url)}" target="_blank" rel="noopener noreferrer nofollow">${esc(f.source_url)}</a> · observado em ${dataBR(f.observed_at)} · ${esc(f.method || 'leitura da página pública')}</p></details>
</section>`).join('');
  const nome = e.nome || 'sua empresa';
  const corpo = `<h1>Diagnóstico rápido do site · ${esc(nome)}</h1>
<p class="sub">${lista.length} ponto(s) verificados em páginas públicas de ${esc(e.dominio || '')}, em ${dataBR(a.observado_em)}. Cada item traz a página e a evidência para você conferir.</p>
${cartoes || '<p>Nenhum ponto listado.</p>'}
${botoes(cfg, nome)}
<section class="card"><h2>Quem preparou</h2><p>A ATOM Digital cria sites, marketing e atendimento com IA para clínicas. Este diagnóstico foi feito a partir do seu site público e revisado por uma pessoa da equipe.</p></section>
<footer>Diagnóstico baseado apenas em páginas públicas acessadas na data indicada; o site pode ter mudado depois. Não mede posição no Google nem citações em ferramentas de IA. Preparado pela ATOM Digital e revisado por uma pessoa. Também pode responder a mensagem do WhatsApp que enviamos.</footer>`;
  const vistas = Number(a.diag_vistas || 0) + 1;
  return {
    status: 200, html: pagina('Diagnóstico · ' + nome, corpo),
    auditoria: { audit_id: a.audit_id, diag_vistas: vistas, diag_visto_em: agora },
    // Primeira visita: tarefa no Pipedrive para responder enquanto o lead está olhando o diagnóstico.
    tarefa: vistas === 1 && e.pipedrive_deal_id ? { deal_id: Number(e.pipedrive_deal_id), subject: 'Lead abriu o diagnóstico agora: responder enquanto está quente', type: 'task', due_date: agora.slice(0, 10) } : null,
    evento: vistas === 1 ? { event_id: 'e_w09_' + a.audit_id + '_primeira_visita', correlation_id: a.audit_id, company_id: a.company_id, workflow: 'ATOM2_W09', tipo: 'DIAGNOSTICO_ABERTO', motivo: 'primeira visita ao link', dados: '{}', ocorrido_em: agora } : null
  };
}


const cfg = Object.fromEntries($('Ler config (página)').all().map((i) => i.json).filter((r) => r && r.chave).map((r) => [r.chave, String(r.valor ?? '')]));
const t = ($('Página (GET)').first().json.query || {}).t;
return [{ json: renderizar(t, $('Ler auditoria pelo token').all().map((i) => i.json), $('Ler empresa').all().map((i) => i.json), $('Ler achados').all().map((i) => i.json), new Date().toISOString(), cfg) }];

// Primeira visita ao diagnóstico: tarefa no Pipedrive para o Thiago responder enquanto o lead está quente.
const r = $('Renderizar').first().json;
return r.tarefa ? [{ json: r.tarefa }] : [];
